import React, { useState, useMemo } from 'react';
import {
  Box,
  TextField,
  Typography,
  Paper,
  Grid,
  Chip,
  IconButton,
  Tooltip,
  Card,
  CardContent,
  InputAdornment,
  Button,
  Tabs,
  Tab,
  Alert
} from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import TerminalIcon from '@mui/icons-material/Terminal';
import BookmarkIcon from '@mui/icons-material/Bookmark';
import BookmarkBorderIcon from '@mui/icons-material/BookmarkBorder';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';

const COMMANDS_DATABASE = [
  // --- Permissions & Access Control ---
  {
    cmd: 'chmod 755 filename',
    title: 'Standard Executable Permissions',
    category: 'Permissions',
    desc: 'Sets rwxr-xr-x: Owner has full read/write/execute; Group and Others have read/execute.',
    flags: '-R (Recursive for directories)',
    tags: ['chmod', 'permissions', '755', 'execute', 'access']
  },
  {
    cmd: 'chmod 644 filename',
    title: 'Standard File Permissions',
    category: 'Permissions',
    desc: 'Sets rw-r--r--: Owner has read/write; Group and Others have read-only.',
    flags: '-v (Verbose output)',
    tags: ['chmod', '644', 'read', 'write', 'file']
  },
  {
    cmd: 'chmod 2770 directory/',
    title: 'SetGID Shared Directory (chmod 2770)',
    category: 'Permissions',
    desc: 'Sets drwxrws---: Owner & Group have full access; Others none. SGID bit (2) forces new files inside to inherit directory group.',
    flags: '2 (SetGID), 4 (SetUID), 1 (Sticky bit)',
    tags: ['chmod 2770', 'sgid', 'setgid', 'special', 'group', 'directory']
  },
  {
    cmd: 'chmod 1777 /tmp',
    title: 'Sticky Bit Directory',
    category: 'Permissions',
    desc: 'Sets drwxrwxrwt: Anyone can write, but only the file owner can delete their own files.',
    flags: '1 (Sticky bit)',
    tags: ['sticky', '1777', 'tmp', 'permissions']
  },
  {
    cmd: 'chmod 600 ~/.ssh/id_rsa',
    title: 'Secure Private Key Permissions',
    category: 'Permissions',
    desc: 'Read/write only for owner; no access for anyone else (required for SSH private keys).',
    flags: '-f (Suppress error messages)',
    tags: ['ssh', '600', 'private key', 'security']
  },
  {
    cmd: 'chown user:group filename',
    title: 'Change File Owner and Group',
    category: 'Permissions',
    desc: 'Change ownership of a file or directory to a specific user and group.',
    flags: '-R (Recursive)',
    tags: ['chown', 'owner', 'group', 'user']
  },
  {
    cmd: 'umask 022',
    title: 'Set Default File Creation Mask',
    category: 'Permissions',
    desc: 'Sets default permissions mask. New files get 644 (666 - 022), directories get 755 (777 - 022).',
    flags: '-S (Symbolic display)',
    tags: ['umask', 'default', 'mask', 'creation']
  },

  // --- File & Directory Operations ---
  {
    cmd: 'ls -la',
    title: 'List Files with Details & Hidden',
    category: 'Files',
    desc: 'List all files including hidden dotfiles with permissions, size, owner, and date.',
    flags: '-h (Human-readable sizes), -t (Sort by time), -S (Sort by size)',
    tags: ['ls', 'list', 'hidden', 'files', 'directory']
  },
  {
    cmd: 'find /var/log -type f -name "*.log" -mtime -7',
    title: 'Find Files Modified in Last 7 Days',
    category: 'Files',
    desc: 'Search for files ending in .log modified within the past 7 days.',
    flags: '-size +100M (Files larger than 100MB), -exec rm {} \\; (Execute command)',
    tags: ['find', 'search', 'mtime', 'log', 'files']
  },
  {
    cmd: 'grep -rnw "searchTerm" /path/to/dir',
    title: 'Recursive Text Search in Files',
    category: 'Files',
    desc: 'Search recursively for an exact word in all files under a directory with line numbers.',
    flags: '-i (Case insensitive), -v (Invert match), -C 3 (Show 3 lines context)',
    tags: ['grep', 'search', 'text', 'regex', 'recursive']
  },
  {
    cmd: 'tail -f -n 100 /var/log/syslog',
    title: 'Follow Live Log Stream',
    category: 'Files',
    desc: 'Display the last 100 lines of a file and stream new lines as they are written in real-time.',
    flags: '-F (Follow by filename, handles log rotation)',
    tags: ['tail', 'log', 'follow', 'stream', 'live']
  },
  {
    cmd: 'cp -r /source/dir /dest/dir',
    title: 'Copy Directory Recursively',
    category: 'Files',
    desc: 'Copy a directory and all of its contents to a destination.',
    flags: '-a (Archive: preserve permissions, timestamps, symlinks)',
    tags: ['cp', 'copy', 'recursive', 'directory']
  },
  {
    cmd: 'rsync -avzP /source/ user@remote:/dest/',
    title: 'Fast Remote Sync with Progress',
    category: 'Files',
    desc: 'Synchronize files locally or remotely with compression, archive mode, and resume capability.',
    flags: '--delete (Delete files in dest that are removed in source)',
    tags: ['rsync', 'sync', 'remote', 'transfer', 'backup']
  },
  {
    cmd: 'tree -L 2',
    title: 'Visual Directory Tree',
    category: 'Files',
    desc: 'Display recursive directory hierarchy as a tree limited to 2 levels deep.',
    flags: '-d (Directories only), -a (All files)',
    tags: ['tree', 'structure', 'hierarchy', 'directory']
  },

  // --- Networking & Connectivity ---
  {
    cmd: 'ss -tulpn',
    title: 'List Listening Ports & Processes',
    category: 'Networking',
    desc: 'Show all listening TCP & UDP sockets with associated process IDs and program names.',
    flags: '-t (TCP), -u (UDP), -l (Listening), -p (Process), -n (Numeric ports)',
    tags: ['ss', 'netstat', 'ports', 'listening', 'sockets', 'network']
  },
  {
    cmd: 'ip addr show',
    title: 'Display Network Interfaces & IP Addresses',
    category: 'Networking',
    desc: 'Display all network interfaces, IPv4, IPv6, and MAC addresses (modern ifconfig replacement).',
    flags: 'ip route show (View default gateway and routing table)',
    tags: ['ip', 'ip addr', 'ifconfig', 'interfaces', 'ipv4', 'ipv6']
  },
  {
    cmd: 'curl -Iv https://example.com',
    title: 'Inspect HTTP Response Headers',
    category: 'Networking',
    desc: 'Fetch HTTP headers only with verbose SSL handshake and connection details.',
    flags: '-L (Follow redirects), -k (Insecure/ignore SSL), -X POST (Specify method)',
    tags: ['curl', 'http', 'headers', 'ssl', 'inspect']
  },
  {
    cmd: 'dig +short example.com A',
    title: 'Quick DNS Lookup',
    category: 'Networking',
    desc: 'Query DNS server for A records and return just the resolved IP addresses.',
    flags: 'dig @8.8.8.8 example.com (Query specific DNS server), +trace (Trace delegation)',
    tags: ['dig', 'dns', 'lookup', 'records', 'nameserver']
  },
  {
    cmd: 'lsof -i :8080',
    title: 'Find Process Using Port 8080',
    category: 'Networking',
    desc: 'Identify which process and PID is actively bound to port 8080.',
    flags: '-iTCP -sTCP:LISTEN (Only show listening TCP sockets)',
    tags: ['lsof', 'port', 'pid', 'process', 'occupying']
  },
  {
    cmd: 'ufw status verbose',
    title: 'Check Firewall Status & Rules',
    category: 'Networking',
    desc: 'Check Ubuntu Uncomplicated Firewall (UFW) active status and opened ports.',
    flags: 'ufw allow 22/tcp (Allow SSH), ufw enable (Enable firewall)',
    tags: ['ufw', 'firewall', 'security', 'ports', 'iptables']
  },

  // --- Process & System Monitoring ---
  {
    cmd: 'ps aux | grep nginx',
    title: 'Find Running Process by Name',
    category: 'Processes',
    desc: 'List all running system processes and filter for processes matching "nginx".',
    flags: 'ps -ef (Standard format), pgrep -l process_name (Quick PID lookup)',
    tags: ['ps', 'process', 'grep', 'pid', 'running']
  },
  {
    cmd: 'kill -9 1234',
    title: 'Force Kill Process by PID',
    category: 'Processes',
    desc: 'Send SIGKILL (signal 9) to forcibly terminate a runaway process with PID 1234.',
    flags: 'kill -15 (SIGTERM: graceful shutdown), killall -9 process_name',
    tags: ['kill', 'sigkill', 'sigterm', 'terminate', 'pid']
  },
  {
    cmd: 'systemctl status service_name',
    title: 'Check Systemd Service Status',
    category: 'Processes',
    desc: 'Check if a background daemon or system service is active, running, or failed.',
    flags: 'systemctl restart / start / stop / enable (Start on boot)',
    tags: ['systemctl', 'systemd', 'service', 'daemon', 'status']
  },
  {
    cmd: 'journalctl -u service_name -f -n 50',
    title: 'Stream Systemd Service Logs',
    category: 'Processes',
    desc: 'Follow live logs generated by a specific systemd service, starting with last 50 lines.',
    flags: '--since "1 hour ago", -p err (Only error logs)',
    tags: ['journalctl', 'logs', 'systemd', 'debug', 'errors']
  },
  {
    cmd: 'htop',
    title: 'Interactive Process & Resource Monitor',
    category: 'Processes',
    desc: 'Visual real-time CPU, RAM, swap, and thread viewer with interactive sort and kill.',
    flags: 'top (Standard fallback built-in on all Unix systems)',
    tags: ['htop', 'top', 'cpu', 'memory', 'ram', 'monitor']
  },

  // --- System Info & Storage ---
  {
    cmd: 'df -h',
    title: 'Check Disk Space Usage',
    category: 'System',
    desc: 'Show available and used disk space on all mounted filesystems in human-readable GB/MB.',
    flags: '-T (Print filesystem type ext4/xfs)',
    tags: ['df', 'disk', 'storage', 'space', 'mounts']
  },
  {
    cmd: 'du -sh * | sort -h',
    title: 'Find Largest Folders in Directory',
    category: 'System',
    desc: 'Calculate total disk usage for each folder in current directory and sort smallest to largest.',
    flags: 'ncdu (Interactive NCurses disk usage analyzer)',
    tags: ['du', 'size', 'disk usage', 'large files', 'cleanup']
  },
  {
    cmd: 'free -h',
    title: 'Check Available RAM and Swap',
    category: 'System',
    desc: 'Display total, used, and available physical RAM and swap space in human-readable units.',
    flags: '-m (Display in MB), -w (Wide output with cache breakdown)',
    tags: ['free', 'ram', 'memory', 'swap', 'performance']
  },
  {
    cmd: 'uname -a',
    title: 'Print Kernel & OS Architecture',
    category: 'System',
    desc: 'Print system architecture (x86_64, aarch64), Linux kernel release, and hostname.',
    flags: 'cat /etc/os-release (Display Linux distribution name and version)',
    tags: ['uname', 'kernel', 'os', 'version', 'architecture']
  },
  {
    cmd: 'crontab -l',
    title: 'List Scheduled Cron Jobs',
    category: 'System',
    desc: 'Display current user scheduled cron jobs and periodic automations.',
    flags: 'crontab -e (Edit cron schedule in default editor)',
    tags: ['crontab', 'cron', 'schedule', 'automation', 'recurring']
  },

  // --- Archiving & Compression ---
  {
    cmd: 'tar -czvf archive.tar.gz /path/to/folder',
    title: 'Create Compressed Tarball (tar.gz)',
    category: 'Archiving',
    desc: 'Compress a folder into a gzip-compressed archive.',
    flags: '-c (Create), -z (gzip), -v (Verbose), -f (Filename)',
    tags: ['tar', 'tar.gz', 'compress', 'archive', 'gzip']
  },
  {
    cmd: 'tar -xzvf archive.tar.gz -C /dest/',
    title: 'Extract Compressed Tarball',
    category: 'Archiving',
    desc: 'Decompress and extract a tar.gz archive into a target directory.',
    flags: '-x (Extract), -C (Change to directory before extracting)',
    tags: ['tar', 'extract', 'unzip', 'untar', 'decompress']
  },
  {
    cmd: 'zip -r archive.zip folder/',
    title: 'Create Standard ZIP Archive',
    category: 'Archiving',
    desc: 'Create a zip file recursively from a directory (compatible with Windows & macOS).',
    flags: 'unzip archive.zip (Extract zip file)',
    tags: ['zip', 'unzip', 'archive', 'compress']
  },

  // --- User & Group Administration ---
  {
    cmd: 'sudo usermod -aG sudo,docker username',
    title: 'Add User to Supplementary Groups',
    category: 'Users',
    desc: 'Append a user to administrative groups (sudo and docker) without removing existing groups.',
    flags: '-a (Append), -G (Group list)',
    tags: ['usermod', 'user', 'groups', 'sudo', 'docker']
  },
  {
    cmd: 'id username',
    title: 'Display User and Group IDs (UID/GID)',
    category: 'Users',
    desc: 'Print real and effective user ID (UID), primary group ID (GID), and all group memberships.',
    flags: 'whoami (Print current logged-in user)',
    tags: ['id', 'uid', 'gid', 'user', 'groups', 'whoami']
  }
];

const CATEGORIES = ['All', 'Permissions', 'Files', 'Networking', 'Processes', 'System', 'Archiving', 'Users'];

const STORAGE_BOOKMARKS_KEY = 'devsuite_linux_cheatsheet_bookmarks';

const LinuxCheatSheet = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [copiedCmd, setCopiedCmd] = useState('');
  const [bookmarks, setBookmarks] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_BOOKMARKS_KEY);
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  });

  const toggleBookmark = (cmd) => {
    const updated = bookmarks.includes(cmd)
      ? bookmarks.filter((b) => b !== cmd)
      : [...bookmarks, cmd];
    setBookmarks(updated);
    try {
      localStorage.setItem(STORAGE_BOOKMARKS_KEY, JSON.stringify(updated));
    } catch (e) {}
  };

  const handleCopy = (cmd) => {
    navigator.clipboard.writeText(cmd);
    setCopiedCmd(cmd);
    setTimeout(() => setCopiedCmd(''), 2000);
  };

  const filteredCommands = useMemo(() => {
    const q = searchTerm.toLowerCase().trim();
    return COMMANDS_DATABASE.filter((item) => {
      const matchesCategory =
        selectedCategory === 'All'
          ? true
          : selectedCategory === 'Bookmarks'
          ? bookmarks.includes(item.cmd)
          : item.category === selectedCategory;

      if (!matchesCategory) return false;
      if (!q) return true;

      return (
        item.cmd.toLowerCase().includes(q) ||
        item.title.toLowerCase().includes(q) ||
        item.desc.toLowerCase().includes(q) ||
        item.flags.toLowerCase().includes(q) ||
        item.tags.some((t) => t.toLowerCase().includes(q))
      );
    });
  }, [searchTerm, selectedCategory, bookmarks]);

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, minHeight: 'calc(100vh - 130px)', animation: 'fadeIn 0.5s ease-in-out' }}>
      {/* Header Banner */}
      <Paper elevation={2} sx={{ p: 3, borderRadius: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 2, mb: 1 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
            <TerminalIcon color="primary" sx={{ fontSize: 36 }} />
            <Box>
              <Typography variant="h4" component="h1" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
                Linux Command Cheat Sheet
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Searchable commands, flags, and syntax for sysadmins, DevOps, and developers.
              </Typography>
            </Box>
          </Box>

          <Button
            variant="outlined"
            color="primary"
            size="small"
            endIcon={<OpenInNewIcon />}
            component="a"
            href="/system/chmod"
          >
            Chmod Calculator Tool
          </Button>
        </Box>

        {/* Search Input */}
        <Box sx={{ mt: 2.5 }}>
          <TextField
            fullWidth
            variant="outlined"
            placeholder="Search commands (e.g. chmod 2770, find, umask, ports, tar, kill)..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon color="action" />
                </InputAdornment>
              ),
              sx: { bgcolor: 'background.default' }
            }}
          />
        </Box>

        {/* Categories Tab Bar */}
        <Box sx={{ mt: 2, borderBottom: 1, borderColor: 'divider', overflowX: 'auto' }}>
          <Tabs
            value={selectedCategory}
            onChange={(e, val) => setSelectedCategory(val)}
            variant="scrollable"
            scrollButtons="auto"
          >
            {CATEGORIES.map((cat) => (
              <Tab key={cat} label={cat} value={cat} sx={{ fontWeight: 600 }} />
            ))}
            <Tab
              label={`Bookmarks (${bookmarks.length})`}
              value="Bookmarks"
              sx={{ fontWeight: 600, color: bookmarks.length ? 'secondary.main' : 'inherit' }}
            />
          </Tabs>
        </Box>
      </Paper>

      {/* Results Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', px: 0.5 }}>
        <Typography variant="body2" color="text.secondary">
          Showing <strong>{filteredCommands.length}</strong> commands
          {searchTerm && ` for "${searchTerm}"`}
        </Typography>
      </Box>

      {/* Command Cards Grid */}
      {filteredCommands.length === 0 ? (
        <Alert severity="info" sx={{ mt: 2 }}>
          No commands matched your query. Try searching for "chmod", "ps", "ip", or "tar".
        </Alert>
      ) : (
        <Grid container spacing={2}>
          {filteredCommands.map((item, idx) => {
            const isBookmarked = bookmarks.includes(item.cmd);
            const isCopied = copiedCmd === item.cmd;

            return (
              <Grid item xs={12} md={6} key={idx}>
                <Card
                  variant="outlined"
                  sx={{
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    borderRadius: 2,
                    transition: 'transform 0.15s, box-shadow 0.15s',
                    '&:hover': {
                      boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                      borderColor: 'primary.light'
                    }
                  }}
                >
                  <CardContent sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
                      <Box>
                        <Typography variant="subtitle1" sx={{ fontWeight: 700, color: 'text.primary' }}>
                          {item.title}
                        </Typography>
                        <Chip
                          label={item.category}
                          size="small"
                          color="primary"
                          variant="outlined"
                          sx={{ height: 20, fontSize: '0.72rem', mt: 0.5 }}
                        />
                      </Box>
                      <Tooltip title={isBookmarked ? 'Remove Bookmark' : 'Bookmark Command'}>
                        <IconButton size="small" onClick={() => toggleBookmark(item.cmd)}>
                          {isBookmarked ? (
                            <BookmarkIcon color="secondary" fontSize="small" />
                          ) : (
                            <BookmarkBorderIcon fontSize="small" />
                          )}
                        </IconButton>
                      </Tooltip>
                    </Box>

                    {/* Terminal Command Box */}
                    <Box
                      sx={{
                        my: 1.5,
                        p: 1.5,
                        bgcolor: '#0f172a',
                        color: '#38bdf8',
                        borderRadius: 1.5,
                        fontFamily: 'monospace',
                        fontSize: '0.9rem',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        border: '1px solid #1e293b'
                      }}
                    >
                      <Box sx={{ overflowX: 'auto', pr: 1, whiteSpace: 'nowrap' }}>
                        <span style={{ color: '#94a3b8', marginRight: 6 }}>$</span>
                        {item.cmd}
                      </Box>
                      <Tooltip title={isCopied ? 'Copied!' : 'Copy Command'}>
                        <IconButton
                          size="small"
                          onClick={() => handleCopy(item.cmd)}
                          sx={{ color: isCopied ? '#4ade80' : '#94a3b8' }}
                        >
                          {isCopied ? <CheckIcon fontSize="small" /> : <ContentCopyIcon fontSize="small" />}
                        </IconButton>
                      </Tooltip>
                    </Box>

                    {/* Description */}
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 1, flexGrow: 1 }}>
                      {item.desc}
                    </Typography>

                    {/* Useful Flags */}
                    {item.flags && (
                      <Box sx={{ mt: 'auto', pt: 1, borderTop: '1px dashed', borderColor: 'divider' }}>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.primary', display: 'block' }}>
                          Key Flags:
                        </Typography>
                        <Typography variant="caption" color="text.secondary" sx={{ fontFamily: 'monospace' }}>
                          {item.flags}
                        </Typography>
                      </Box>
                    )}
                  </CardContent>
                </Card>
              </Grid>
            );
          })}
        </Grid>
      )}
    </Box>
  );
};

export default LinuxCheatSheet;
