import React, { useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  Chip,
  Button,
  IconButton,
  Tooltip,
  Alert,
  Grid,
  useTheme
} from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import DownloadIcon from '@mui/icons-material/Download';
import ContentPasteIcon from '@mui/icons-material/ContentPaste';
import DeleteSweepIcon from '@mui/icons-material/DeleteSweep';
import FullscreenIcon from '@mui/icons-material/Fullscreen';
import FullscreenExitIcon from '@mui/icons-material/FullscreenExit';
import SecurityIcon from '@mui/icons-material/Security';

/**
 * Standardized Developer Tool Workbench Layout
 * Provides a unified, high-density, accessible two-pane interface following UI/UX Pro Max principles.
 */
export const ToolWorkbench = ({
  title,
  category = 'UTILITY',
  description,
  headerActions,
  inputTitle = 'INPUT',
  inputSubtitle,
  inputActions,
  onPaste,
  onClear,
  inputContent,
  outputTitle = 'OUTPUT',
  outputSubtitle,
  outputActions,
  outputValue = '',
  outputFileName = 'output.txt',
  outputMimeType = 'text/plain',
  outputContent,
  error,
  statusMessage,
  executionTime,
  children
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const [copied, setCopied] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const handleCopy = () => {
    if (!outputValue) return;
    navigator.clipboard.writeText(outputValue).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const handleDownload = () => {
    if (!outputValue) return;
    const blob = new Blob([outputValue], { type: outputMimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = outputFileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const workbenchStyles = isFullscreen
    ? {
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        zIndex: 1300,
        p: { xs: 2, md: 3 },
        overflowY: 'auto',
        backgroundColor: theme.palette.background.default
      }
    : {
        width: '100%',
        mb: 4
      };

  return (
    <Box sx={workbenchStyles} className="animate-fade-in">
      {/* 1. Tool Header */}
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 2.5 },
          mb: 2.5,
          borderRadius: 2,
          border: '1px solid',
          borderColor: 'divider',
          backgroundColor: 'background.paper',
          display: 'flex',
          flexDirection: { xs: 'column', md: 'row' },
          justifyContent: 'space-between',
          alignItems: { xs: 'flex-start', md: 'center' },
          gap: 2
        }}
      >
        <Box>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 0.5, flexWrap: 'wrap' }}>
            <Typography variant="h5" component="h1" sx={{ fontWeight: 700, color: 'text.primary' }}>
              {title}
            </Typography>
            {category && (
              <Chip
                label={category}
                size="small"
                sx={{
                  fontWeight: 700,
                  fontSize: '0.68rem',
                  letterSpacing: '0.06em',
                  bgcolor: isDark ? 'rgba(99, 102, 241, 0.15)' : 'rgba(79, 70, 229, 0.1)',
                  color: isDark ? '#a5b4fc' : '#4f46e5',
                  border: '1px solid',
                  borderColor: isDark ? 'rgba(99, 102, 241, 0.3)' : 'rgba(79, 70, 229, 0.2)',
                  borderRadius: 1
                }}
              />
            )}
          </Box>
          {description && (
            <Typography variant="body2" sx={{ color: 'text.secondary', maxWidth: 800 }}>
              {description}
            </Typography>
          )}
        </Box>

        {/* Global Toolbar Actions (e.g. sample load, format toggles, fullscreen) */}
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', width: { xs: '100%', md: 'auto' } }}>
          {headerActions}
          <Tooltip title={isFullscreen ? 'Exit Fullscreen' : 'Expand Fullscreen'}>
            <IconButton
              size="small"
              onClick={() => setIsFullscreen(!isFullscreen)}
              sx={{
                border: '1px solid',
                borderColor: 'divider',
                borderRadius: 1.5,
                color: 'text.secondary'
              }}
            >
              {isFullscreen ? <FullscreenExitIcon fontSize="small" /> : <FullscreenIcon fontSize="small" />}
            </IconButton>
          </Tooltip>
        </Box>
      </Paper>

      {/* Error Banner */}
      {error && (
        <Alert
          severity="error"
          sx={{
            mb: 2.5,
            borderRadius: 2,
            fontFamily: 'var(--font-mono, monospace)',
            fontSize: '0.85rem'
          }}
        >
          {error}
        </Alert>
      )}

      {/* 2. Workspace Body: Two-Pane Split View or Custom Children */}
      {children ? (
        children
      ) : (
        <Grid container spacing={2.5}>
          {/* Left Pane: Input */}
          <Grid item xs={12} lg={6}>
            <Paper
              elevation={0}
              sx={{
                borderRadius: 2,
                border: '1px solid',
                borderColor: 'divider',
                backgroundColor: 'background.paper',
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                height: '100%'
              }}
            >
              {/* Input Pane Header */}
              <Box
                sx={{
                  px: 2,
                  py: 1.25,
                  borderBottom: '1px solid',
                  borderColor: 'divider',
                  bgcolor: isDark ? 'rgba(255, 255, 255, 0.02)' : 'rgba(0, 0, 0, 0.02)',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                  <Typography
                    variant="caption"
                    sx={{
                      fontWeight: 700,
                      letterSpacing: '0.08em',
                      color: 'text.secondary',
                      textTransform: 'uppercase'
                    }}
                  >
                    {inputTitle}
                  </Typography>
                  {inputSubtitle && (
                    <Typography variant="caption" sx={{ color: 'text.secondary', fontFamily: 'var(--font-mono, monospace)' }}>
                      {inputSubtitle}
                    </Typography>
                  )}
                </Box>

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  {inputActions}
                  {onPaste && (
                    <Tooltip title="Paste from clipboard">
                      <IconButton size="small" onClick={onPaste} sx={{ color: 'text.secondary' }}>
                        <ContentPasteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  )}
                  {onClear && (
                    <Tooltip title="Clear Input">
                      <IconButton size="small" onClick={onClear} sx={{ color: 'text.secondary' }}>
                        <DeleteSweepIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  )}
                </Box>
              </Box>

              {/* Input Pane Body */}
              <Box sx={{ p: 2, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                {inputContent}
              </Box>
            </Paper>
          </Grid>

          {/* Right Pane: Output */}
          <Grid item xs={12} lg={6}>
            <Paper
              elevation={0}
              sx={{
                borderRadius: 2,
                border: '1px solid',
                borderColor: 'divider',
                backgroundColor: 'background.paper',
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                height: '100%'
              }}
            >
              {/* Output Pane Header */}
              <Box
                sx={{
                  px: 2,
                  py: 1.25,
                  borderBottom: '1px solid',
                  borderColor: 'divider',
                  bgcolor: isDark ? 'rgba(255, 255, 255, 0.02)' : 'rgba(0, 0, 0, 0.02)',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                  <Typography
                    variant="caption"
                    sx={{
                      fontWeight: 700,
                      letterSpacing: '0.08em',
                      color: 'text.secondary',
                      textTransform: 'uppercase'
                    }}
                  >
                    {outputTitle}
                  </Typography>
                  {executionTime && (
                    <Chip
                      label={executionTime}
                      size="small"
                      sx={{
                        height: 20,
                        fontSize: '0.7rem',
                        fontFamily: 'var(--font-mono, monospace)',
                        bgcolor: isDark ? 'rgba(16, 185, 129, 0.15)' : 'rgba(16, 185, 129, 0.1)',
                        color: isDark ? '#6ee7b7' : '#059669',
                        borderRadius: 1
                      }}
                    />
                  )}
                  {outputSubtitle && (
                    <Typography variant="caption" sx={{ color: 'text.secondary', fontFamily: 'var(--font-mono, monospace)' }}>
                      {outputSubtitle}
                    </Typography>
                  )}
                </Box>

                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  {outputActions}
                  {outputValue && (
                    <>
                      <Tooltip title={copied ? 'Copied to clipboard!' : 'Copy output'}>
                        <Button
                          size="small"
                          variant="outlined"
                          onClick={handleCopy}
                          startIcon={copied ? <CheckIcon sx={{ color: '#10b981' }} /> : <ContentCopyIcon />}
                          sx={{
                            fontSize: '0.75rem',
                            py: 0.3,
                            px: 1,
                            borderColor: copied ? '#10b981' : 'divider',
                            color: copied ? '#10b981' : 'text.primary',
                            '&:hover': {
                              borderColor: copied ? '#10b981' : 'primary.main'
                            }
                          }}
                        >
                          {copied ? 'Copied' : 'Copy'}
                        </Button>
                      </Tooltip>
                      <Tooltip title="Download as file">
                        <IconButton size="small" onClick={handleDownload} sx={{ color: 'text.secondary' }}>
                          <DownloadIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </>
                  )}
                </Box>
              </Box>

              {/* Output Pane Body */}
              <Box sx={{ p: 2, flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
                {outputContent}
              </Box>
            </Paper>
          </Grid>
        </Grid>
      )}

      {/* 3. Bottom Status Bar */}
      <Box
        sx={{
          mt: 2,
          px: 1,
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 1
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <SecurityIcon sx={{ fontSize: 16, color: '#10b981' }} />
          <Typography variant="caption" sx={{ color: 'text.secondary' }}>
            100% Client-Side Execution. Your data never leaves your browser.
          </Typography>
        </Box>

        {statusMessage && (
          <Typography
            variant="caption"
            sx={{
              fontFamily: 'var(--font-mono, monospace)',
              color: 'text.secondary'
            }}
          >
            {statusMessage}
          </Typography>
        )}
      </Box>
    </Box>
  );
};

export default ToolWorkbench;
