import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  Tabs,
  Tab,
  Box,
  TextField,
  Button,
  Typography,
  Alert,
  Divider,
  CircularProgress
} from '@mui/material';
import GitHubIcon from '@mui/icons-material/GitHub';
import LockOpenIcon from '@mui/icons-material/LockOpen';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import { useAuth, API_BASE } from '../../context/AuthContext';

const AuthModal = ({ open, onClose }) => {
  const [tab, setTab] = useState(0); // 0 = Login, 1 = Register
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const { login, register } = useAuth();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      if (tab === 0) {
        await login(email, password);
      } else {
        await register(name, email, password);
      }
      onClose();
    } catch (err) {
      setError(err.message || 'Authentication failed. Please check credentials.');
    } finally {
      setLoading(false);
    }
  };

  const handleGitHubOAuth = () => {
    // Redirect to Spring Boot OAuth2 GitHub initiation endpoint
    window.location.href = `${API_BASE}/oauth2/authorization/github`;
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle sx={{ textAlign: 'center', pb: 1, fontWeight: 'bold' }}>
        {tab === 0 ? 'Welcome to DevSuite' : 'Create Your DevSuite Account'}
      </DialogTitle>

      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs value={tab} onChange={(e, val) => { setTab(val); setError(''); }} variant="fullWidth">
          <Tab icon={<LockOpenIcon />} iconPosition="start" label="Sign In" sx={{ fontWeight: 600 }} />
          <Tab icon={<PersonAddIcon />} iconPosition="start" label="Register" sx={{ fontWeight: 600 }} />
        </Tabs>
      </Box>

      <DialogContent sx={{ pt: 3 }}>
        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {/* GitHub OAuth Button */}
        <Button
          fullWidth
          variant="contained"
          startIcon={<GitHubIcon />}
          onClick={handleGitHubOAuth}
          sx={{
            bgcolor: '#24292e',
            color: '#fff',
            py: 1.2,
            mb: 2,
            textTransform: 'none',
            fontWeight: 600,
            '&:hover': { bgcolor: '#1b1f23' }
          }}
        >
          Continue with GitHub
        </Button>

        <Box sx={{ display: 'flex', alignItems: 'center', my: 2 }}>
          <Divider sx={{ flexGrow: 1 }} />
          <Typography variant="caption" color="text.secondary" sx={{ px: 1.5 }}>
            OR WITH EMAIL
          </Typography>
          <Divider sx={{ flexGrow: 1 }} />
        </Box>

        <Box component="form" onSubmit={handleSubmit} sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {tab === 1 && (
            <TextField
              fullWidth
              label="Full Name"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          )}

          <TextField
            fullWidth
            label="Email Address"
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />

          <TextField
            fullWidth
            label="Password"
            type="password"
            required
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />

          <Button
            type="submit"
            fullWidth
            variant="contained"
            color="primary"
            size="large"
            disabled={loading}
            sx={{ mt: 1, py: 1.2, fontWeight: 'bold' }}
          >
            {loading ? <CircularProgress size={24} color="inherit" /> : tab === 0 ? 'Sign In' : 'Create Account'}
          </Button>
        </Box>
      </DialogContent>
    </Dialog>
  );
};

export default AuthModal;

