import React, { useState, useEffect, useMemo } from 'react';
import { ThemeProvider, createTheme, CssBaseline, Box } from '@mui/material';
import Header from './components/Header';
import MainContent from './components/MainContent';
import { AuthProvider, API_BASE } from './context/AuthContext';
import './index.css';

function App() {
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return localStorage.getItem("theme") !== "light";
  });
  const [currentRoute, setCurrentRoute] = useState(window.location.pathname || "/");
  const [search, setSearch] = useState("");
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem("theme", isDarkMode ? "dark" : "light");
  }, [isDarkMode]);

  // Standard History Routing & Popstate Listener
  useEffect(() => {
    const handlePopState = () => {
      setCurrentRoute(window.location.pathname || "/");
    };
    window.addEventListener("popstate", handlePopState);
    return () => {
      window.removeEventListener("popstate", handlePopState);
    };
  }, []);

  // Global Anchor Click Interceptor for Clean SPA Routing
  useEffect(() => {
    const handleGlobalClick = (e) => {
      const anchor = e.target.closest("a");
      if (
        anchor &&
        anchor.href &&
        anchor.host === window.location.host &&
        !anchor.getAttribute("download") &&
        anchor.getAttribute("target") !== "_blank"
      ) {
        e.preventDefault();
        const path = anchor.pathname;
        if (window.location.pathname !== path) {
          window.history.pushState(null, "", path);
          setCurrentRoute(path);
        }
      }
    };
    document.addEventListener("click", handleGlobalClick);
    return () => {
      document.removeEventListener("click", handleGlobalClick);
    };
  }, []);

  // Track Page and Tool Usage in Database on route changes (instant transition, no blocking spinner)
  useEffect(() => {
    try {
      fetch(`${API_BASE}/api/track/page`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          pagePath: currentRoute,
          pageTitle: document.title || 'DevSuite'
        })
      }).catch(() => {});
    } catch (e) {}
  }, [currentRoute]);

  const theme = useMemo(
    () =>
      createTheme({
        palette: {
          mode: isDarkMode ? 'dark' : 'light',
          primary: {
            main: isDarkMode ? '#6366f1' : '#4f46e5', // Vibrant Indigo
            light: isDarkMode ? '#818cf8' : '#6366f1',
            dark: isDarkMode ? '#4f46e5' : '#3730a3',
            contrastText: '#ffffff'
          },
          secondary: {
            main: '#10b981', // Terminal / Mint Green
            contrastText: '#ffffff'
          },
          background: {
            default: isDarkMode ? '#0b0f19' : '#f8fafc', // OLED Slate 950 / Slate 50
            paper: isDarkMode ? '#111827' : '#ffffff',   // Slate 900 / Pure White
          },
          divider: isDarkMode ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.08)',
          text: {
            primary: isDarkMode ? '#f8fafc' : '#0f172a',
            secondary: isDarkMode ? '#94a3b8' : '#64748b',
          }
        },
        typography: {
          fontFamily: '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
          h5: {
            fontWeight: 700,
            letterSpacing: '-0.02em',
          },
          h6: {
            fontWeight: 600,
            letterSpacing: '-0.01em',
          },
          subtitle1: {
            letterSpacing: '-0.01em',
          },
          button: {
            textTransform: 'none',
            fontWeight: 600,
          }
        },
        shape: {
          borderRadius: 8, // Sharp, modern developer tool radius
        },
        components: {
          MuiButton: {
            styleOverrides: {
              root: {
                textTransform: 'none',
                fontWeight: 600,
                borderRadius: 6,
                boxShadow: 'none',
                transition: 'all 0.15s ease-in-out',
                '&:hover': {
                  boxShadow: 'none',
                }
              },
              containedPrimary: {
                backgroundColor: isDarkMode ? '#6366f1' : '#4f46e5',
                '&:hover': {
                  backgroundColor: isDarkMode ? '#4f46e5' : '#4338ca',
                }
              }
            }
          },
          MuiAppBar: {
            styleOverrides: {
              root: {
                backgroundColor: isDarkMode ? '#0b0f19' : '#ffffff',
                color: isDarkMode ? '#f8fafc' : '#0f172a',
                backgroundImage: 'none',
                borderBottom: isDarkMode ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid rgba(0, 0, 0, 0.08)',
                boxShadow: 'none',
              },
            },
          },
          MuiDrawer: {
            styleOverrides: {
              paper: {
                backgroundColor: isDarkMode ? '#0b0f19' : '#ffffff',
                backgroundImage: 'none',
                borderRight: isDarkMode ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid rgba(0, 0, 0, 0.08)',
              },
            },
          },
          MuiCard: {
            styleOverrides: {
              root: {
                backgroundImage: 'none',
                backgroundColor: isDarkMode ? '#111827' : '#ffffff',
                border: isDarkMode ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid rgba(0, 0, 0, 0.08)',
                boxShadow: isDarkMode ? '0 1px 3px 0 rgba(0, 0, 0, 0.37)' : '0 1px 3px 0 rgba(0, 0, 0, 0.05)',
                borderRadius: 8,
              }
            }
          },
          MuiPaper: {
            styleOverrides: {
              root: {
                backgroundImage: 'none',
              }
            }
          },
          MuiOutlinedInput: {
            styleOverrides: {
              root: {
                borderRadius: 6,
                '& fieldset': {
                  borderColor: isDarkMode ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.15)',
                },
                '&:hover fieldset': {
                  borderColor: isDarkMode ? '#818cf8' : '#6366f1',
                },
                '&.Mui-focused fieldset': {
                  borderColor: isDarkMode ? '#6366f1' : '#4f46e5',
                }
              }
            }
          }
        }
      }),
    [isDarkMode],
  );

  return (
    <AuthProvider>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Box sx={{ display: 'flex', minHeight: '100vh', bgcolor: 'background.default' }}>
          <Header 
            isDarkMode={isDarkMode} 
            setIsDarkMode={setIsDarkMode} 
            search={search} 
            setSearch={setSearch}
            mobileOpen={mobileOpen}
            setMobileOpen={setMobileOpen}
          />
          
          <MainContent 
            search={search} 
            setSearch={setSearch}
            mobileOpen={mobileOpen}
            setMobileOpen={setMobileOpen}
            currentRoute={currentRoute}
          />
        </Box>
      </ThemeProvider>
    </AuthProvider>
  );
}

export default App;
