import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const API_BASE = process.env.REACT_APP_API_BASE || '';

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(() => localStorage.getItem('devsuite_jwt') || '');
  const [loading, setLoading] = useState(true);

  // Check token and handle GitHub OAuth2 redirect query params
  useEffect(() => {
    const handleAuthInit = async () => {
      // 1. Check for token in URL query (from GitHub OAuth redirect)
      const params = new URLSearchParams(window.location.search);
      const urlToken = params.get('token');

      let activeToken = token;
      if (urlToken) {
        localStorage.setItem('devsuite_jwt', urlToken);
        setToken(urlToken);
        activeToken = urlToken;
        // Clean URL without refresh and redirect to home if on callback route
        params.delete('token');
        const cleanSearch = params.toString() ? `?${params.toString()}` : '';
        const targetPath = window.location.pathname.startsWith('/callback/oauth') ? '/' : window.location.pathname;
        window.history.replaceState({}, document.title, targetPath + cleanSearch);
      }

      // 2. Fetch current user if token exists
      if (activeToken) {
        try {
          const res = await fetch(`${API_BASE}/api/auth/me`, {
            headers: {
              'Authorization': `Bearer ${activeToken}`,
              'Content-Type': 'application/json'
            }
          });
          if (res.ok) {
            const data = await res.json();
            setUser(data);
          } else {
            // Token expired or invalid
            localStorage.removeItem('devsuite_jwt');
            setToken('');
            setUser(null);
          }
        } catch (e) {
          console.warn('Backend not reachable or offline', e);
        }
      }
      setLoading(false);
    };

    handleAuthInit();
  }, []);

  const login = async (email, password) => {
    const res = await fetch(`${API_BASE}/api/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password })
    });

    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.message || 'Invalid credentials');
    }

    const data = await res.json();
    localStorage.setItem('devsuite_jwt', data.token);
    setToken(data.token);
    setUser(data);
    return data;
  };

  const register = async (name, email, password) => {
    const res = await fetch(`${API_BASE}/api/auth/register`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, email, password })
    });

    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.message || 'Registration failed');
    }

    const data = await res.json();
    localStorage.setItem('devsuite_jwt', data.token);
    setToken(data.token);
    setUser(data);
    return data;
  };

  const logout = () => {
    localStorage.removeItem('devsuite_jwt');
    setToken('');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, token, loading, login, register, logout, isAuthenticated: !!user }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

