import React, { useState, useEffect } from 'react';
import {
  Box,
  TextField,
  Button,
  Typography,
  Paper,
  Tabs,
  Tab,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Alert
} from '@mui/material';
import AutoFixHighIcon from '@mui/icons-material/AutoFixHigh';
import CompressIcon from '@mui/icons-material/Compress';
import AccountTreeIcon from '@mui/icons-material/AccountTree';
import CodeIcon from '@mui/icons-material/Code';
import vkbeautify from 'vkbeautify';
import ToolWorkbench from '../common/ToolWorkbench';

const SAMPLE_XML = `<?xml version="1.0" encoding="UTF-8"?>
<catalog>
  <book id="bk101">
    <author>Gambardella, Matthew</author>
    <title>XML Developer's Guide</title>
    <genre>Computer</genre>
    <price currency="USD">44.95</price>
    <publish_date>2000-10-01</publish_date>
    <description>An in-depth look at creating applications with XML.</description>
  </book>
  <book id="bk102">
    <author>Ralls, Kim</author>
    <title>Midnight Rain</title>
    <genre>Fantasy</genre>
    <price currency="USD">5.95</price>
    <publish_date>2000-12-16</publish_date>
    <description>A former architect battles corporate zombies.</description>
  </book>
</catalog>`;

const XmlTreeNode = ({ node }) => {
  const [collapsed, setCollapsed] = useState(false);

  if (node.nodeType === 3) {
    const val = node.nodeValue?.trim();
    if (!val) return null;
    return <span style={{ color: '#10b981', fontFamily: 'var(--font-mono, monospace)' }}>"{val}"</span>;
  }

  if (node.nodeType !== 1) return null;

  const hasChildren = Array.from(node.childNodes).some(
    (c) => c.nodeType === 1 || (c.nodeType === 3 && c.nodeValue?.trim().length > 0)
  );

  const attributes = Array.from(node.attributes || []).map((attr) => (
    <span key={attr.name} style={{ marginLeft: 6 }}>
      <span style={{ color: '#f59e0b' }}>{attr.name}</span>=
      <span style={{ color: '#38bdf8' }}>"{attr.value}"</span>
    </span>
  ));

  return (
    <Box sx={{ ml: 2, my: 0.3, fontFamily: 'var(--font-mono, monospace)', fontSize: '0.86rem' }}>
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          cursor: hasChildren ? 'pointer' : 'default',
          userSelect: 'none',
          py: 0.2
        }}
        onClick={() => hasChildren && setCollapsed(!collapsed)}
      >
        {hasChildren && (
          <span style={{ display: 'inline-block', width: 14, color: '#94a3b8', fontSize: '0.75rem' }}>
            {collapsed ? '▶' : '▼'}
          </span>
        )}
        <span style={{ color: '#818cf8', fontWeight: 600 }}>&lt;{node.nodeName}</span>
        {attributes}
        <span style={{ color: '#818cf8', fontWeight: 600 }}>&gt;</span>
        {collapsed && hasChildren && <span style={{ color: '#64748b', marginLeft: 4 }}>... &lt;/{node.nodeName}&gt;</span>}
      </Box>

      {!collapsed && hasChildren && (
        <Box sx={{ borderLeft: '1px dashed rgba(148, 163, 184, 0.3)', pl: 1, ml: 0.5 }}>
          {Array.from(node.childNodes).map((child, idx) => (
            <XmlTreeNode key={idx} node={child} />
          ))}
        </Box>
      )}

      {!collapsed && hasChildren && (
        <Box sx={{ color: '#818cf8', fontWeight: 600, ml: 2 }}>
          &lt;/{node.nodeName}&gt;
        </Box>
      )}
    </Box>
  );
};

const XmlBeautifier = () => {
  const [inputXml, setInputXml] = useState(SAMPLE_XML);
  const [outputXml, setOutputXml] = useState('');
  const [indentSize, setIndentSize] = useState('2');
  const [activeView, setActiveView] = useState('editor'); // 'editor' | 'tree'
  const [validationError, setValidationError] = useState('');
  const [xmlDoc, setXmlDoc] = useState(null);
  const [execTime, setExecTime] = useState('');

  const validateAndFormat = (xmlStr, formatType = 'beautify') => {
    const raw = xmlStr.trim();
    if (!raw) {
      setOutputXml('');
      setValidationError('');
      setXmlDoc(null);
      setExecTime('');
      return;
    }

    const t0 = performance.now();
    try {
      const parser = new DOMParser();
      const doc = parser.parseFromString(raw, 'text/xml');
      const parseError = doc.querySelector('parsererror');

      if (parseError) {
        setValidationError(parseError.textContent.split('\n')[0]);
        setOutputXml('');
        setXmlDoc(null);
        setExecTime('');
        return;
      }

      setValidationError('');
      setXmlDoc(doc);

      let formatted = '';
      if (formatType === 'beautify') {
        const step = indentSize === '4' ? '    ' : '  ';
        formatted = vkbeautify.xml(raw, step);
      } else {
        formatted = vkbeautify.xmlmin(raw);
      }
      setOutputXml(formatted);
      const elapsed = (performance.now() - t0).toFixed(1);
      setExecTime(`${elapsed}ms`);
    } catch (e) {
      setValidationError(e.message);
      setExecTime('');
    }
  };

  useEffect(() => {
    validateAndFormat(inputXml, 'beautify');
  }, [inputXml, indentSize]);

  const handleMinify = () => {
    validateAndFormat(inputXml, 'minify');
  };

  const handleClear = () => {
    setInputXml('');
    setOutputXml('');
    setValidationError('');
    setXmlDoc(null);
    setExecTime('');
  };

  const handlePaste = async () => {
    try {
      const text = await navigator.clipboard.readText();
      if (text) setInputXml(text);
    } catch (e) {}
  };

  const inputLines = inputXml ? inputXml.split('\n').length : 0;
  const inputBytes = new Blob([inputXml]).size;
  const outputLines = outputXml ? outputXml.split('\n').length : 0;
  const outputBytes = new Blob([outputXml]).size;

  const headerActions = (
    <>
      <Button
        variant="contained"
        color="primary"
        size="small"
        startIcon={<AutoFixHighIcon />}
        onClick={() => validateAndFormat(inputXml, 'beautify')}
      >
        Beautify
      </Button>
      <Button
        variant="outlined"
        color="inherit"
        size="small"
        startIcon={<CompressIcon />}
        onClick={handleMinify}
        sx={{ borderColor: 'divider' }}
      >
        Minify
      </Button>

      <FormControl size="small" sx={{ minWidth: 110 }}>
        <InputLabel id="indent-select-label">Indent</InputLabel>
        <Select
          labelId="indent-select-label"
          label="Indent"
          value={indentSize}
          onChange={(e) => setIndentSize(e.target.value)}
          sx={{ height: 32, fontSize: '0.8rem' }}
        >
          <MenuItem value="2">2 Spaces</MenuItem>
          <MenuItem value="4">4 Spaces</MenuItem>
        </Select>
      </FormControl>

      <Button
        size="small"
        variant="text"
        onClick={() => setInputXml(SAMPLE_XML)}
        sx={{ fontSize: '0.8rem', color: 'text.secondary' }}
      >
        Sample
      </Button>
    </>
  );

  const outputTabs = (
    <Tabs
      value={activeView}
      onChange={(e, val) => setActiveView(val)}
      textColor="primary"
      indicatorColor="primary"
      sx={{ minHeight: 32, '& .MuiTab-root': { minHeight: 32, py: 0, px: 1.5, fontSize: '0.75rem', fontWeight: 600 } }}
    >
      <Tab value="editor" label="Code" icon={<CodeIcon sx={{ fontSize: 16 }} />} iconPosition="start" />
      <Tab value="tree" label="Tree" icon={<AccountTreeIcon sx={{ fontSize: 16 }} />} iconPosition="start" />
    </Tabs>
  );

  return (
    <ToolWorkbench
      title="XML Beautifier & Tree Viewer"
      category="FORMATTER & VALIDATOR"
      description="Format, indent, minify, validate, and inspect XML with interactive collapsible tree views."
      headerActions={headerActions}
      inputTitle="RAW XML"
      inputSubtitle={`${inputLines} lines • ${inputBytes} B`}
      onPaste={handlePaste}
      onClear={handleClear}
      inputContent={
        <TextField
          fullWidth
          multiline
          variant="outlined"
          placeholder="Paste or type raw XML here..."
          value={inputXml}
          onChange={(e) => setInputXml(e.target.value)}
          className="code-editor-textarea"
          sx={{
            flexGrow: 1,
            '& .MuiInputBase-root': {
              height: '100%',
              alignItems: 'flex-start',
              fontFamily: 'var(--font-mono, monospace)',
              fontSize: '0.85rem'
            },
            '& textarea': {
              height: '100% !important',
              fontFamily: 'var(--font-mono, monospace) !important',
              fontSize: '0.85rem !important'
            }
          }}
          minRows={18}
        />
      }
      outputTitle="FORMATTED OUTPUT"
      outputSubtitle={outputXml ? `${outputLines} lines • ${outputBytes} B` : ''}
      outputValue={outputXml}
      outputFileName="formatted.xml"
      outputMimeType="application/xml"
      outputActions={outputTabs}
      executionTime={execTime}
      error={validationError ? `XML Error: ${validationError}` : null}
      statusMessage={outputXml && !validationError ? '✓ Valid, well-formed XML' : ''}
      outputContent={
        activeView === 'editor' ? (
          <TextField
            fullWidth
            multiline
            variant="outlined"
            placeholder="Formatted XML will appear here..."
            value={outputXml}
            className="code-editor-textarea"
            InputProps={{
              readOnly: true,
              sx: {
                fontFamily: 'var(--font-mono, monospace)',
                fontSize: '0.85rem',
                bgcolor: 'background.default'
              }
            }}
            sx={{
              flexGrow: 1,
              '& .MuiInputBase-root': {
                height: '100%',
                alignItems: 'flex-start'
              },
              '& textarea': {
                height: '100% !important',
                fontFamily: 'var(--font-mono, monospace) !important',
                fontSize: '0.85rem !important'
              }
            }}
            minRows={18}
          />
        ) : (
          <Box sx={{ p: 2, bgcolor: 'background.default', borderRadius: 1.5, border: '1px solid', borderColor: 'divider', height: '100%', overflowX: 'auto', minHeight: 400 }}>
            {xmlDoc && xmlDoc.documentElement ? (
              <XmlTreeNode node={xmlDoc.documentElement} />
            ) : (
              <Alert severity="info" sx={{ mt: 1 }}>
                Enter well-formed XML to view its hierarchical tree structure.
              </Alert>
            )}
          </Box>
        )
      }
    />
  );
};

export default XmlBeautifier;
